select extensions.plan(13);
select extensions.lives_ok($$select pg_temp.aportar(11,100,'1')$$,'Primer aporte promocional desde Bs100');
select extensions.throws_like($$select pg_temp.aportar(11,300,'2')$$,'%aportes_prestamo_id_prestamista_id_key%','Un solo aporte por persona y préstamo');
select extensions.throws_like($$select pg_temp.aportar(13,100,'3')$$,'%fuera de límites%','Fuera de la primera semana no aplica la promoción');
select extensions.throws_like($$select pg_temp.aportar(12,501,'3')$$,'%fuera de límites%','Aporte sobre 50% rechazado');
select extensions.lives_ok($$select pg_temp.aportar(12,400,'2')$$,'Aporte ordinario válido');
select extensions.throws_like($$select pg_temp.aportar(14,300,'2')$$,'%aportes_tx_hash_key%','Un hash repetido no duplica una transferencia');
select extensions.is((select monto_recaudado::numeric from public.prestamos where id='00000000-0000-4000-8000-000000000101'),500::numeric,'Saldo financiado deriva de los aportes');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000011","role":"authenticated"}';
set local role authenticated;
select extensions.is((select count(*)::int from public.aportes),1,'Prestamista consulta solo su aporte');
select extensions.is((select cantidad_prestamistas::int from public.resumen_financiamiento where prestamo_id='00000000-0000-4000-8000-000000000101'),2,'Ve el número agregado de prestamistas');
select extensions.throws_like($$insert into public.aportes(prestamo_id,prestamista_id,monto,tx_hash) values('00000000-0000-4000-8000-000000000101',auth.uid(),300,repeat('f',64))$$,'%verificada%','El cliente no fabrica un aporte confirmado');
reset role;
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}';
set local role authenticated;
select extensions.is((select count(*)::int from public.aportes),2,'Emprendedor consulta aportes de su préstamo');
reset role;
update public.prestamos set estado='cancelado' where id='00000000-0000-4000-8000-000000000101';
update public.aportes set monto_devuelto=50,devolucion_tx_hash=repeat('d',64) where prestamista_id='00000000-0000-4000-8000-000000000011';
select extensions.is((select monto::numeric from public.aportes where prestamista_id='00000000-0000-4000-8000-000000000011'),100::numeric,'Devolución parcial conserva aporte original');
select extensions.throws_like($$update public.aportes set monto_devuelto=101 where prestamista_id='00000000-0000-4000-8000-000000000011'$$,'%check constraint%','Nunca se devuelve más que el aporte');
select * from extensions.finish();
